FILL={"CEBRA":"DCE6F1","Soft":"E2F0D9","conv-piVAE":"FCE4D6","t-SNE":"FFF2CC","UMAP":"E4DFEC","Ridge":"FCE4D6","Traiettorie":"E7E6E6"}
def build(path,title,subtitle,rows,refs):
    wb=Workbook(); ws=wb.active; ws.title="Specifiche"; ws.sheet_view.showGridLines=True
    n=len(HEADERS)
    for r,text,color,size,bold in [(1,title,"17365D",15,True),(2,subtitle,"DDEBF7",10,False),(3,"Legenda: PAPER = caption/codice plotting; LOCALE = runner e manifest; SCELTA/DIFF = scelta o scostamento locale. cebra-figures contiene plotting di risultati precomputati, non i fit originali.","FFF2CC",10,False)]:
        ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=n); c=ws.cell(r,1,text); c.fill=PatternFill("solid",fgColor=color); c.font=Font(name="Calibri",size=size,bold=bold,color="FFFFFF" if r==1 else "1F1F1F"); c.alignment=Alignment(wrap_text=True,vertical="center")
    ws.row_dimensions[1].height=30; ws.row_dimensions[2].height=32; ws.row_dimensions[3].height=36
    panels=list(dict.fromkeys(x[0] for x in rows)); rr=5; thin=Side(style="thin",color=GRID)
    for p in panels:
        ws.merge_cells(start_row=rr,start_column=1,end_row=rr,end_column=n); c=ws.cell(rr,1,"PANNELLO "+p); c.fill=PatternFill("solid",fgColor="17365D"); c.font=Font(bold=True,color="FFFFFF",size=12); ws.row_dimensions[rr].height=24; rr+=1
        for j,h in enumerate(HEADERS,1):
            c=ws.cell(rr,j,h); c.fill=PatternFill("solid",fgColor="4472C4"); c.font=Font(bold=True,color="FFFFFF",size=9); c.alignment=Alignment(wrap_text=True,horizontal="center",vertical="center"); c.border=Border(left=thin,right=thin,top=thin,bottom=thin)
        ws.row_dimensions[rr].height=34; rr+=1
        for k,row in enumerate(x for x in rows if x[0]==p):
            cat=next((v for v in FILL if v.lower() in row[1].lower()),None); base=FILL.get(cat,"FFFFFF" if k%2==0 else "F4F7FA")
            nlines=1
            for j,val in enumerate(row,1):
                c=ws.cell(rr,j,val); c.font=Font(name="Calibri",size=9,color="1F1F1F"); c.fill=PatternFill("solid",fgColor=base if j==2 else ("FFFFFF" if k%2==0 else "F7FAFC")); c.alignment=Alignment(wrap_text=True,vertical="top"); c.border=Border(left=thin,right=thin,top=thin,bottom=thin); nlines=max(nlines,math.ceil(len(str(val or ""))/max(9,WIDTHS[j-1]-3)))
            ws.row_dimensions[rr].height=min(90,max(38,15*nlines)); rr+=1
        rr+=1
    ws.merge_cells(start_row=rr,start_column=1,end_row=rr,end_column=n); c=ws.cell(rr,1,"RIFERIMENTI E TRACCIABILITÀ"); c.fill=PatternFill("solid",fgColor="17365D"); c.font=Font(bold=True,color="FFFFFF",size=12); ws.row_dimensions[rr].height=24; rr+=1
    for key,val in refs:
        ws.cell(rr,1,key).font=Font(bold=True,color="17365D",size=9); ws.merge_cells(start_row=rr,start_column=2,end_row=rr,end_column=n); ws.cell(rr,2,val)
        for c in ws[rr][:n]: c.alignment=Alignment(wrap_text=True,vertical="top"); c.border=Border(left=thin,right=thin,top=thin,bottom=thin)
        ws.row_dimensions[rr].height=32 if len(val)<130 else 42; rr+=1
    for i,w in enumerate(WIDTHS,1): ws.column_dimensions[get_column_letter(i)].width=w
    ws.freeze_panes="A7"; ws.sheet_view.zoomScale=75; ws.sheet_properties.pageSetUpPr.fitToPage=True; ws.page_setup.orientation="landscape"; ws.page_setup.paperSize=ws.PAPERSIZE_A3; ws.page_setup.fitToWidth=1; ws.page_setup.fitToHeight=0; ws.print_title_rows="1:3"
    path.parent.mkdir(parents=True,exist_ok=True); tmp=path.with_name(path.stem+".building.xlsx"); wb.save(tmp)
    chk=load_workbook(tmp,read_only=True,data_only=True); sh=chk["Specifiche"]; assert sh.max_column==13 and sh.max_row>40 and sh["A1"].value==title; chk.close(); os.replace(tmp,path)
    chk=load_workbook(path,read_only=True,data_only=True); assert chk["Specifiche"].max_row>40; chk.close()

def main():
    assert FIG3.is_file(), f"Figure 3 workbook not found: {FIG3}"
    assert not ED8.exists(), f"Refusing to overwrite ED8 workbook: {ED8}"
    build(FIG3,"FIGURA 3 — SPECIFICHE DEI FIT E DEI PANNELLI","Aggiornato 29-10-2026. Fit descrittivi 3b–3g: recording completo; decoding 3h–3i: split held-out per trial. Distinzione esplicita fra paper e configurazione locale.",F3,REF3)
    build(ED8,"EXTENDED DATA FIGURE 8 — MODEL SPECIFICATIONS","Aggiornato 29-10-2026. CEBRA/InfoMSE separato dai fit Soft sperimentali. Soft 8f incompleto: 7/50 fit per architettura nello snapshot 2026-10-29.",E8,REF8)
    print(f"UPDATED {FIG3} ({FIG3.stat().st_size} bytes; {len(F3)} rows)")
    print(f"CREATED {ED8} ({ED8.stat().st_size} bytes; {len(E8)} rows)")

if __name__=="__main__": main()
